export function renderReturnNotificationEmail(
  body: Record<string, unknown>,
  attachmentCount = 0,
): string {
  const assetBase = pick(body, "asset_base_url", "assetBaseUrl") || DEFAULT_EMAIL_ASSET_BASE;
  const so = displayOrNone(pick(body, "so", "so_number"));
  const customer = displayOrNone(pick(body, "customer"));
  const details = displayOrNone(pick(body, "details", "comments", "notes"));
  const chat = emailAssetUrl("icon-chat", assetBase);
  const clipboard = emailAssetUrl("icon-clipboard", assetBase);
  const cardsHtml = detailCard({
    iconUrl: clipboard,
    title: "RETURN DETAILS",
    rows: [
      { label: "SO#", value: so },
      { label: "Customer", value: customer },
    ],
  }) + detailCard({
    iconUrl: chat,
    title: "NOTES",
    rows: [{ label: "Details", value: details }],
  });

  return renderBrandedNotificationEmail({
    title: "Return Notification",
    headline: "Return notification",
    subtitle: "The following return was reported from SLST:",
    preheader: `Return notification for SO ${so}`,
    cardsHtml,
    attachmentCount,
    assetBaseUrl: assetBase,
  });
}

export function renderReturnToStockEmail(
