export function renderPoNotificationEmail(
  body: Record<string, unknown>,
  attachmentCount = 0,
): string {
  const assetBase = pick(body, "asset_base_url", "assetBaseUrl") || DEFAULT_EMAIL_ASSET_BASE;
  const po = displayOrNone(pick(body, "po", "po_number"));
  const customer = displayOrNone(pick(body, "customer"));
  const so = displayOrNone(pick(body, "so", "so_number", "linked_so", "linkedSo"));
  const details = displayOrNone(pick(body, "details", "comments", "notes"));
  const clipboard = emailAssetUrl("icon-clipboard", assetBase);
  const chat = emailAssetUrl("icon-chat", assetBase);
  const rows: Array<{ label: string; value: string }> = [
    { label: "PO#", value: po },
    { label: "Customer", value: customer },
  ];
  if (so !== "None") rows.push({ label: "Linked SO#", value: so });
  const cardsHtml = detailCard({
    iconUrl: clipboard,
    title: "PO NOTIFICATION",
    rows,
  }) + detailCard({
    iconUrl: chat,
    title: "DETAILS",
    rows: [{ label: "Notes", value: details }],
  });

  return renderBrandedNotificationEmail({
    title: "PO Notification",
    headline: "PO notification",
    subtitle: "Purchase order notification from SLST:",
    preheader: `PO notification: ${po}`,
    cardsHtml,
    attachmentCount,
    assetBaseUrl: assetBase,
  });
}

export function renderNotificationEmail(
  notificationType: string,
  body: Record<string, unknown>,
  attachmentCount = 0,
): string | null {
  const t = notificationType.trim().toLowerCase();
  switch (t) {
    case "return_notification":
      return renderReturnNotificationEmail(body, attachmentCount);
    case "return_to_stock":
      return renderReturnToStockEmail(body, attachmentCount);
    case "po_notification":
      return renderPoNotificationEmail(body, attachmentCount);
    default:
      return null;
  }
}

